//go:build linux
package modem

import("context";"errors";"fmt";"os";"path/filepath";"strings";"time";"golang.org/x/sys/unix")
const port="/dev/ttyUSB3"
var queries=[]string{"AT","AT+CPIN?","AT+CEREG?","AT+CGATT?","AT+CGACT?","AT+QNWINFO","AT+QSPN","AT+QENG=\"servingcell\""}
func unowned()error{pids,e:=os.ReadDir("/proc");if e!=nil{return e};for _,p:=range pids{if p.Name()==fmt.Sprint(os.Getpid())||p.Name()==""||p.Name()[0]<'0'||p.Name()[0]>'9'{continue};dir:="/proc/"+p.Name()+"/fd";fds,e:=os.ReadDir(dir);if os.IsPermission(e){return errors.New("cannot verify AT channel ownership")};for _,f:=range fds{target,e:=os.Readlink(dir+"/"+f.Name());if e==nil&&target==port{return errors.New("AT channel owned by another process")}}};return nil}
func Probe(ctx context.Context)(map[string]string,error){
 if e:=unowned();e!=nil{return nil,e};device,e:=filepath.EvalSymlinks("/sys/class/tty/ttyUSB3/device");if e!=nil{return nil,e};for device!="/"{if _,e:=os.Stat(device+"/idVendor");e==nil{break};device=filepath.Dir(device)};vendor,_:=os.ReadFile(device+"/idVendor");product,_:=os.ReadFile(device+"/idProduct");if strings.TrimSpace(string(vendor))!="2c7c"||strings.TrimSpace(string(product))!="0125"{return nil,errors.New("unverified modem")}
 if e=os.MkdirAll("/run/np1-modem-observer",0700);e!=nil{return nil,e};lock,e:=os.OpenFile("/run/np1-modem-observer/at.lock",os.O_CREATE|os.O_RDWR,0600);if e!=nil{return nil,e};defer lock.Close();if e=unix.Flock(int(lock.Fd()),unix.LOCK_EX|unix.LOCK_NB);e!=nil{return nil,errors.New("AT query already in progress")};defer unix.Flock(int(lock.Fd()),unix.LOCK_UN)
 fd,e:=unix.Open(port,unix.O_RDWR|unix.O_NONBLOCK|unix.O_NOCTTY,0);if e!=nil{return nil,e};defer unix.Close(fd);if e=unowned();e!=nil{return nil,e};original,e:=unix.IoctlGetTermios(fd,unix.TCGETS);if e!=nil{return nil,e};raw:=*original;raw.Iflag=0;raw.Oflag=0;raw.Lflag=0;raw.Cflag=unix.CS8|unix.CREAD|unix.CLOCAL|unix.B115200;raw.Ispeed=unix.B115200;raw.Ospeed=unix.B115200;raw.Cc[unix.VMIN]=0;raw.Cc[unix.VTIME]=0;if e=unix.IoctlSetTermios(fd,unix.TCSETS,&raw);e!=nil{return nil,e};defer unix.IoctlSetTermios(fd,unix.TCSETS,original)
 result:=map[string]string{};for _,query:=range queries{if e=ctx.Err();e!=nil{return result,e};if _,e=unix.Write(fd,[]byte(query+"\r"));e!=nil{return result,e};var response strings.Builder;until:=time.Now().Add(2*time.Second);for time.Now().Before(until){if e=ctx.Err();e!=nil{return result,e};fds:=[]unix.PollFd{{Fd:int32(fd),Events:unix.POLLIN}};n,e:=unix.Poll(fds,150);if e!=nil&&e!=unix.EINTR{return result,e};if n==0{continue};if fds[0].Revents&(unix.POLLHUP|unix.POLLERR)!=0{return result,errors.New("AT channel disconnected")};buffer:=make([]byte,4096);n,e=unix.Read(fd,buffer);if e==unix.EAGAIN{continue};if e!=nil{return result,e};response.Write(buffer[:n]);text:=response.String();if strings.Contains(text,"\r\nOK\r\n")||strings.Contains(text,"\r\nERROR\r\n")||strings.Contains(text,"+CME ERROR:"){break};if response.Len()>16384{return result,errors.New("AT response exceeded limit")}};result[query]=response.String();if query=="AT"&&!strings.Contains(response.String(),"OK"){return result,errors.New("secondary AT channel did not answer")}}
 return result,nil
}
